import{_ as a,O as i,o as r,c as s,a as n,i as d,f as o}from"./chunks/framework.fmIt2z2h.js";const h=JSON.parse('{"title":"A.1　HV01 结构域（完整接口卡）","description":"","frontmatter":{"title":"A.1　HV01 结构域（完整接口卡）","xkChars":1543,"xkLessons":{"A.1":{"title":"A.1　HV01 结构域（完整接口卡）","lead":"HV01先登记候选人类对象，再按G1检验有限分组增益；有共同名称不等于有统一意志，更不等于取得处置权。","explanation":["原文定位：第3568—3633行，原站定位/theory/appendix-a/a-01#section-a-1。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“D0只声明候选人类对象。”HV01首先允许说清楚“我们在研究哪些人、材料、边界和窗口”，并不要求先证明这个分组已成为有效结构域。它把候选命名与预注册G1实例支持分开，避免名字、共处地点或共同问题被偷换成客观统一意志。[T-main；T-D0]","R0（HV01-R0-candidate-object）在D0完整而尚无合格且supported的G1-instance时，允许登记候选对象、材料集合、边界争议和补证需求。R0可以给HV02—HV11传带范围和不确定性的对象引用，因此未完成G1不必让所有后续描述失语；但下游不得把这个引用写成已支持结构域。[T-main]","R1（HV01-R1-effective-domain）要求同一对象、尺度、窗口、K、外推单元中的预注册G1-instance获得supported，并追加E4协议。它支持的是相对匹配N0在预选结果上超过阈值的有限分组增益，范围绑定预注册SP/T/K与generalization_unit。对象真实存在的领域依据与分组预测/解释增益不同，不能用增益证明终极本体、共同意志或管辖权。[T-main；T-G1]","R0/R1不是人格高低或组织成熟度。现有材料可以支持有意义的边界观察，而未支持正式G1；反过来，某个分组在某结果上有增益，也不能推出全部成员愿望一致，或对被排除者实施处置。跨尺度必须补单位总体、代表性、J轴和低可见位置，不能由局部成员替所有受影响者发言。[T-main]","申诉聚焦边界、代表性和同一性判据，要能由成员及受影响位置安全、反报复地提出，并引向原命名/决定链外的复核。获准回滚时，不只改掉结构域名称，还要撤销其对下游对象范围的效力、恢复材料集合、保留版本并验证完成；实际记录和权利调整仍须有效权限。[T-main]","DWP的FRS2023—2024在同一调查中区分household、family/benefit unit和individual层级。这可作对象口径登记的现实对照，不能据官方定义本身声称满足G1，也不把某统计单位当全部家庭权利的边界。下列39字段保留原卡全部登记，再分别解释其责任。[P-FRS；T-main]","39字段逐项研读（以下“原卡”保留该字段全部内容；“解读”明确其作用和不可替代的责任）。","01｜接口 ID（id）。原卡：HV01 解读：这是卡册内的短标识，追踪同一接口，不表示现实对象已被证明。 [T-main]","02｜限定 ID（qualified_id）。原卡：human_variable:HV01 解读：限定命名空间用于避免同名碰撞；引用此ID仍须携带对象和证据状态。 [T-main]","03｜名称（name）。原卡：结构域 解读：名称给出阅读入口，不是对具体人、群体或现实结构的自动标签。 [T-main]","04｜主张类型（claim_type）。原卡：H 解读：H表示人类实例/接口命题的角色；不能把它升级为形式证明或无条件世界规律。 [T-main]","05｜合同角色（contract_role）。原卡：human_variable_interface 解读：这是变量接口合同，规定怎样接入分析；字段存在不等于经验实例已经成立。 [T-main]","06｜命题（proposition）。原卡：D0只声明候选人类对象；只有预注册G1-instance显示候选分组相对匹配N0在预选结果上取得超过阈值的样本外或外推增益时，才在该实例范围登记有限有效结构域。 解读：核心是两层资格：D0够用来声明候选；预注册G1对匹配N0有相称外推增益才支持有限有效结构域，两者不可倒置。 [T-main]","07｜适用范围（scope）。原卡：关系、团队、组织、制度与公共议题 解读：范围列出可考察的任务领域，不代表范围内所有对象已获实证支持。 [T-main]","08｜暂停条件（pause_condition）。原卡：对象、边界、尺度、时间窗或同一性不足以支持所选路由；申请G1正式支持时，相应零模型或实例合同不完整 解读：暂停针对所依赖的判断或采用；独立成立的描述可以保留，但不能继续使用失效前提。 [T-main]","09｜推理依赖（inferential_requires）。原卡：1. D0 解读：推理依赖提供命题成立所需的上游内容；上游的候选/支持状态必须原样传递，引用不自动升格。 [T-main]","10｜协议依赖（protocol_requires）。原卡：1. E1；2. EVIDENCE；3. SOURCE 解读：协议依赖约束取证和表达方式；完成协议不单独证明经验命题为真。 [T-main]","11｜限定／特化（specializes）。原卡：无（空集合） 解读：空集合只说明没有登记这类特化关系，不说明没有证据责任；非空时也不等于普遍有效。 [T-main]","12｜适用对象引用（applies_to）。原卡：无（空集合） 解读：适用对象引用不能代替当前对象合同；空集合是明确登记，不是所有对象都可用。 [T-main]","13｜条件支持路由（conditional_support_routes）。原卡：1. route_id=HV01-R0-candidate-object；；claim_level=candidate_description；；when=D0对象合同完整，但尚无符合资格且result_state=supported的G1-instance。；；additional_inferential_requires=无（空集合）；；additional_protocol_requires=无（空集合）；；allowed_conclusion=登记候选人类对象、材料集合、边界争议与G1补证需求。；；result_ceiling=仅到候选对象描述；可向HV02-HV11提供带边界与不确定性的对象引用，不把这一引用当作G1已支持的有效结构域。；2. route_id=HV01-R1-effective-domain；；claim_level=descriptive_classification；；when=同一对象、尺度、窗口、K与外推单元内的预注册G1-instance取得supported。；；additional_inferential_requires=G1-instance；；additional_protocol_requires=E4；；allowed_conclusion=登记该实例范围内的有限有效结构域、对象识别强度、边界可信度和适用窗。；；result_ceiling=只限预注册SP/T/K与generalization_unit；不得作终极本体、统一意志或授权判断。 解读：R0可向其他HV传候选对象但保留不确定性；R1须合格G1-instance=supported及E4。不得把R0的弱条件接成R1的有效结构域结论。 [T-main]","14｜允许推论（allowed_inference）。原卡：1. R0可登记候选对象、边界争议与有限描述引用；2. 只在G1-instance预注册对象、尺度、窗口、结果与外推单位内登记其增益所支持的有限有效结构域及识别强度 解读：这是允许谈论的结论方向；实际达到哪一项、到什么强度，仍由所选路由及材料限定。 [T-main]","15｜禁止跳跃（prohibited_leap）。原卡：1. 命名即客观共同体2. 共同处境即共同意愿 解读：这些是常见越界，不是换个措辞就能避开；检查实际推断和后续使用，而非只看用词。 [T-main]","16｜九轴尺度画像（scale_profile）。原卡：SP=<A,X,T,O,C,R,I,N,J>；A=聚合层次：关系或事件单元、候选成员总体、边界内外分布及分组规则；X=空间范围：共同场所、组织边界、数字平台与跨域外部环境；T=时间跨度：识别窗口、成员变动周期与边界历史；O=组织层级：角色、团队、组织、制度至治理生态；C=因果层次：原始事件、互动机制、中观关系结构、制度与系统条件；R=观察分辨率：原始互动、事件序列、成员个案、边界分布、指标与摘要，并登记压缩损失；I=影响范围：直接成员、被排除者、间接受影响者、二阶外溢、跨域与代际位置；N=网络拓扑范围：成员关系、边界连接、孤立点与跨域桥接；J=管辖与授权范围：对象命名、边界采用及后续处置分别登记授权；不适用轴须登记not_applicable理由 解读：九轴逐项登记；尤其影响范围I不产生管辖权限J，观察分辨率R降低时须保留压缩损失。 [T-main]","17｜有效对象（effective_object）。原卡：由D0声明的候选对象；只有通过预注册G1-instance相对匹配N0的阈值检验后，才在该实例范围登记为有限有效结构域 解读：候选对象不等于不存在；“有限有效”在此专指G1实例检验支持的范围，并不是关于该对象终极实在性的裁决。 [T-main]","18｜跨尺度保持项（scale_invariants）。原卡：1. 对象合同2. 参与与受影响位置 解读：保持项是迁移时须守住的比较责任，不是宣称所有尺度上的变量数值不变。 [T-main]","19｜升格必补项（required_scale_additions）。原卡：1. 单位与总体；2. 代表性；3. J轴；4. 低可见位置 解读：升格不是把原表复制放大。新增总体、接口和责任位置等材料未齐时，限制依赖它们的结论。 [T-main]","20｜随尺度改变项（changing_semantics）。原卡：1. 有效成员、关系和同一性可随尺度改变 解读：同一词在对象或尺度改变后可能变义，应重建对应而非假定原含义原样适用。 [T-main]","21｜不适用对象（non_applicable_objects）。原卡：1. 无意向、制度或责任接口的非人系统 解读：不适用约束防止人类规范、责任和体验接口被无条件投射；不等于否认其他理论可研究这些对象。 [T-main]","22｜禁止升格（forbidden_elevation）。原卡：1. 局部群体直接代表全部受影响者 解读：局部向整体的推断必须另证；影响广、名称大或形式相似都不能补代表性和授权。 [T-main]","23｜状态集合（state）。原卡：1. 候选2. 可识别3. 边界争议4. 不成立 解读：状态是待证描述分类，不是给人评分的成熟阶梯；状态改变须有窗口、依据与版本。 [T-main]","24｜可观测项（observables）。原卡：1. 边界内外关系密度与约束差异；2. 成员进入、退出与被排除记录；3. 共同问题、资源通道或制度规则的重复共现；4. 改变分组规则后对象识别是否稳定 解读：可观测线索回答到哪里找材料；单一线索的存在还不是完整机制或因果效应的证明。 [T-main]","25｜证据要求（evidence）。原卡：1. D0候选对象与同一性记录；2. G1-instance预注册表及匹配N0；3. 训练与样本外或外推结果；4. 候选分组与竞争分组的增益比较 解读：这列包含申请G1所需材料，不应读成R0日常描述或普通服务也必须先完成全部G1。取得证据依具体路线和任务相关性。 [T-main]","26｜输入依赖与接口内容（input_dependencies）。原卡：1. D0只提供候选对象字段，不构成结构成立证据；2. 预注册G1-instance及匹配N0、阈值、模型类、样本或外推单位；3. 观察位置、竞争分组与E1协议 解读：这里说明上游传入什么及其资格；缺口不能在接口间传递时被悄悄抹掉。 [T-main]","27｜输出效应与变量流（output_effects）。原卡：1. R0向其余变量提供候选对象引用、边界、时间窗与不确定性；R1另提供G1所支持的有限有效范围；2. 对象存在及领域事实的依据与分组增益分别保留 解读：变量流说明哪些下游判断可能依赖本接口；传递引用不保证下游结论、实际修复或授权成立。 [T-main]","28｜时间窗与时滞（time_window_and_lag）。原卡：登记识别窗口、边界变动与成员变化时滞 解读：发生、观察、执行和效果到达可能不同时；窗口外延不能由短期材料自动认证。 [T-main]","29｜不确定性（uncertainty）。原卡：记录边界争议、成员缺席和观察覆盖 解读：把不确定性指向具体材料和位置，不能只写一个总置信分而掩盖根本未覆盖的位置。 [T-main]","30｜局部排除区（local_exclusion_zone）。原卡：无法安全表达或未被采样的位置不得被总体代表 解读：排除区限制当前推断覆盖，不是把这些人或事实从世界删除；安全不可得也不是同意或无问题。 [T-main]","31｜受影响位置（affected_positions）。原卡：1. 成员2. 被排除者3. 边界外成本承担者 解读：同时登记直接和间接受影响者；可见成员不代表全部成本承担者。 [T-main]","32｜承接载体（carrier）。原卡：1. 关系网络2. 组织边界3. 制度记录 解读：载体是实际承载的结构或过程；载体名称、建设完成和所需功能到达是不同证据。 [T-main]","33｜责任主体（responsible_subject）。原卡：1. 提出结构域判断的分析者；2. 使用该判断的决策者 解读：说明谁提出判断、谁操作或使用；责任登记不自动等于法律责任裁判或新授权。 [T-main]","34｜规范地位（normative_status）。原卡：描述性H-World接口，不产生正当性 解读：按卡片区分描述、规范和桥接身份。事实成立不独立决定价值排序，规范理由不自动证明经验效果。 [T-main]","35｜判断上限（judgment_ceiling）。原卡：只有G1-instance通过时，且仅限预注册对象、尺度、窗口、结果与外推单位，才可登记解释级有限有效对象；否则仅为候选对象或材料集合 解读：此处上界是解释级有限有效对象，且绑定预注册结果和外推单位；没有G1支持时仍可以保留R0候选与材料集合。 [T-main]","36｜行动上限（action_ceiling）。原卡：本变量只生成候选结构域、边界争议与补证需求描述，不授权纳入、排除或处置；任何现实调整须另过C12、运行时显式N前提、J授权与O程序 解读：接口本身不产生现实处置权；实际动作另核选择、C12、显式N、有效J、O及保护和期限。 [T-main]","37｜反例（counterexamples）。原卡：1. 同一场所中反复共现的人群没有稳定关系或共同约束；2. 分析者划定的群组在改变分组规则后立即消失 解读：用反例限定无条件外推；反例可能要求缩小范围或重新取证，不自动否定所有有限用法。 [T-main]","38｜申诉（appeal）。原卡：依appeal_and_rollback_rule，成员与受影响位置可经安全可达、反报复通道挑战边界、代表性和同一性判据，并触发与原命名或决策链独立的复核 解读：申诉要安全可达、免于报复并能触发独立复核；只留一个名称不代表有权改变错误。 [T-main]","39｜回滚（rollback）。原卡：依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内实际撤销结构域登记、移除其对下游对象范围的效力并恢复为材料集合，保留版本与完成验证 解读：在有效授权内实际撤销错误效力、纠正下游并验证完成；文档改字不等于权利资源恢复到当事人。 [T-main]"],"argumentSteps":["用D0固定对象、边界、尺度、窗口和K。","尚无合格supported的G1实例时走R0，只输出候选描述及补证需求。","申请R1时冻结结果、模型类、匹配N0、阈值和外推单位，依G1实例判定。","把实例支持限制在预注册范围；下游接收同样的证据状态。","成员、被排除者、边界外成本承担者都能质疑代表与边界。","若边界判断撤回，按有效程序消除下游效力并验证，不从接口直接处置。"],"distinctions":[{"leftTitle":"候选对象","leftText":"D0已说明研究指向。","rightTitle":"有限有效结构域","rightText":"特定预注册G1实例支持其有限增益。"},{"leftTitle":"分组有用","leftText":"在指定结果与比较中增益成立。","rightTitle":"统一意志","rightText":"不能由统计分组推出。"},{"leftTitle":"对象存在依据","leftText":"领域事实说明有人或关系存在。","rightTitle":"G1增益依据","rightText":"比较分组是否改善指定结果，不互相代证。"},{"leftTitle":"描述引用","leftText":"可传给后续HV并保留候选身份。","rightTitle":"正式支持传递","rightText":"不能靠引用自动从R0升R1。"}],"boundaries":["原卡反例：同一场所反复共现的人群没有稳定关系或共同约束。","原卡反例：划定群组改变分组规则后立即消失。","教学反例：共同受某政策影响便宣称所有人同意同一代表，跳过意愿与代表授权。","原文边界：无法安全表达或未采样的位置不得由总体直接代表。"],"questions":["无G1支持是不是不能描述任何关系或边界？","分组增益足够，能否宣布共同意愿？","R1撤回后仅删名称够吗？","空specializes代表无需证据吗？"],"diagramPath":"/reading-assets/S-A-1/figures/hv01-routes.png","caseLinks":[{"title":"FRS中的不同统计对象层级","href":"https://www.gov.uk/government/statistics/family-resources-survey-financial-year-2023-to-2024/family-resources-survey-financial-year-2023-to-2024"}],"caseNotes":[{"title":"FRS中的不同统计对象层级","text":"DWP2023—2024家庭资源调查分别定义共同居住统计户、family/benefit unit和individual层级。","sourceLabel":"DWP：Family Resources Survey 2023—2024","sourceUrl":"https://www.gov.uk/government/statistics/family-resources-survey-financial-year-2023-to-2024/family-resources-survey-financial-year-2023-to-2024","sourceLocator":"§2 Households, benefit units and individuals，网页行171—184","boundary":"只支持口径可区别；未检验G1，不证明任何群体共同意志、一般法律家庭边界或处置权限。","href":"https://www.gov.uk/government/statistics/family-resources-survey-financial-year-2023-to-2024/family-resources-survey-financial-year-2023-to-2024"}],"sourceRefs":[{"section":"A.1","start_line":3568,"end_line":3633,"startLine":3568,"endLine":3633}],"outputId":"section-a-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：数值过线只是实例判断的一部分","text":"人工预先冻结“越高越好”的结果分数、匹配N0和阈值5分；同一外推评估中候选分组78分、匹配N0为70分，差值8分超过5。这里只完成设定中的数值比较；还须冻结合法、证据独立、比较匹配、误差和判定规则等条件，不能仅凭8>5宣布现实G1已supported。若范围是这类团队本季度，也不能外推全国或共同意志。","assumptions":"所有分数与阈值为教学构造，不是实测样本或实际G1实例。","boundary":"没有用人工过线充当正式supported资格；更不产生现实纳入排除权限。"},{"title":"教学构造：候选引用仍可工作","text":"人工材料涉及同一楼栋住户，但尚未做G1。可在R0固定住户候选范围和缺席者，交HV02描述出入口及资源接口；不得把“有楼栋名单”写成全体意愿，也不能因G1未做而拒绝普通安全支持。","assumptions":"虚构楼栋与人员，无个人资料。","boundary":"描述入口可用不等于其因果效果或全部领域事实已证实。"}],"counterexamples":[{"identity":"source_counterexample","text":"原卡反例：同一场所反复共现的人群没有稳定关系或共同约束。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原卡反例：划定群组改变分组规则后立即消失。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：共同受某政策影响便宣称所有人同意同一代表，跳过意愿与代表授权。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：无法安全表达或未采样的位置不得由总体直接代表。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"无G1支持是不是不能描述任何关系或边界？","answer":"不是；D0完整可走R0候选描述，向其他HV传带不确定性的引用。","basis":"HV01-R0。"},{"question":"分组增益足够，能否宣布共同意愿？","answer":"不能；R1只支持预注册结果和范围，不支持统一意志或授权。","basis":"R1上限及禁止跳跃。"},{"question":"R1撤回后仅删名称够吗？","answer":"不够；需按有效程序撤下游效力、保留版本并验证完成。","basis":"原卡rollback。"},{"question":"空specializes代表无需证据吗？","answer":"不代表；只是这类依赖空集合，其他合同仍有效。","basis":"附录导语及B区。"}],"figures":[{"path":"/reading-assets/S-A-1/figures/hv01-routes.png","alt":"D0完整可R0候选；合格预注册G1 supported加E4才可R1有限有效结构域；两者都不证明统一意志或权限。","caption":"据A.1两条完整路由；不是成熟阶梯。"},{"path":"/reading-assets/S-A-1/figures/hv01-boundaries.png","alt":"对象范围、G1比较、下游状态、受影响位置申诉与撤销效力分别核。","caption":"据A.1的39字段；8与5为正文教学数值，不在图中冒充实测。"}],"diagramBrief":"路由图将R0候选与R1实例支持分开；字段图列五区的证据和保护流。箭头是引用依赖，不是人格评级，也不授权纳入排除。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["没有真实预注册G1-instance及其结果，所有数值只是教学构造，不签发supported。","具体对象的代表性、缺席位置、安全申诉、独立复核与回滚需实际记录和权限。"],"taskId":"S-A-1","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§A.1，第3568—3633行","claim_support":["HV01全部39字段及R0/R1条件路由。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-intro","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§intro-17-appendix-a，第3562—3567行","claim_support":["五区39字段、材料状态、空集合与整路阅读。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-D0","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§3.1，第425—450行","claim_support":["D0候选对象定义。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-G1","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.3，第602—609行","claim_support":["G1候选分组的条件增益。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-FRS","title":"DWP：Family Resources Survey 2023—2024","url":"https://www.gov.uk/government/statistics/family-resources-survey-financial-year-2023-to-2024/family-resources-survey-financial-year-2023-to-2024","source_type":"primary","version_or_date":"2023—2024调查；页面更新2026-01-15","locator":"§2 Households, benefit units and individuals，网页行171—184","claim_support":["同一调查分别定义household、family/benefit unit和individual统计层级。"],"limits":["本人定点读定义；只说明统计对象口径，不证明G1分组增益，也不把benefit unit当一般法律家庭。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-A-1/lecture.md","sourcesPath":"/reading-assets/S-A-1/sources.json","sourceSlicePath":"/reading-assets/S-A-1/source/S-A-1.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-A-1/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-a/a-01.md","filePath":"theory/appendix-a/a-01.md"}'),l={name:"theory/appendix-a/a-01.md"};function c(u,t,_,p,m,b){const e=i("SectionLesson");return r(),s("div",null,[t[0]||(t[0]=n('<div class="theory-source"><h1 id="section-a-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">A.1</span><span class="xk-num__gap">　</span></span>HV01 结构域（完整接口卡） <a class="header-anchor" href="#section-a-1" aria-label="Permalink to &quot;A.1　HV01 结构域（完整接口卡） {#section-a-1}&quot;">​</a></h1><p>A. 身份、命题与适用范围</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>接口 ID（id）</td><td>HV01</td></tr><tr><td>限定 ID（qualified_id）</td><td>human_variable:HV01</td></tr><tr><td>名称（name）</td><td>结构域</td></tr><tr><td>主张类型（claim_type）</td><td>H</td></tr><tr><td>合同角色（contract_role）</td><td>human_variable_interface</td></tr><tr><td>命题（proposition）</td><td>D0只声明候选人类对象；只有预注册G1-instance显示候选分组相对匹配N0在预选结果上取得超过阈值的样本外或外推增益时，才在该实例范围登记有限有效结构域。</td></tr><tr><td>适用范围（scope）</td><td>关系、团队、组织、制度与公共议题</td></tr><tr><td>暂停条件（pause_condition）</td><td>对象、边界、尺度、时间窗或同一性不足以支持所选路由；申请G1正式支持时，相应零模型或实例合同不完整</td></tr></tbody></table></div><p>B. 正式依赖与结论边界</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>推理依赖（inferential_requires）</td><td>1. D0</td></tr><tr><td>协议依赖（protocol_requires）</td><td>1. E1<br>2. EVIDENCE<br>3. SOURCE</td></tr><tr><td>限定／特化（specializes）</td><td>无（空集合）</td></tr><tr><td>适用对象引用（applies_to）</td><td>无（空集合）</td></tr><tr><td>条件支持路由（conditional_support_routes）</td><td>1. route_id=HV01-R0-candidate-object；<br>claim_level=candidate_description；<br>when=D0对象合同完整，但尚无符合资格且result_state=supported的G1-instance。；<br>additional_inferential_requires=无（空集合）；<br>additional_protocol_requires=无（空集合）；<br>allowed_conclusion=登记候选人类对象、材料集合、边界争议与G1补证需求。；<br>result_ceiling=仅到候选对象描述；可向HV02-HV11提供带边界与不确定性的对象引用，不把这一引用当作G1已支持的有效结构域。<br>2. route_id=HV01-R1-effective-domain；<br>claim_level=descriptive_classification；<br>when=同一对象、尺度、窗口、K与外推单元内的预注册G1-instance取得supported。；<br>additional_inferential_requires=G1-instance；<br>additional_protocol_requires=E4；<br>allowed_conclusion=登记该实例范围内的有限有效结构域、对象识别强度、边界可信度和适用窗。；<br>result_ceiling=只限预注册SP/T/K与generalization_unit；不得作终极本体、统一意志或授权判断。</td></tr><tr><td>允许推论（allowed_inference）</td><td>1. R0可登记候选对象、边界争议与有限描述引用<br>2. 只在G1-instance预注册对象、尺度、窗口、结果与外推单位内登记其增益所支持的有限有效结构域及识别强度</td></tr><tr><td>禁止跳跃（prohibited_leap）</td><td>1. 命名即客观共同体2. 共同处境即共同意愿</td></tr></tbody></table></div><p>C. 九轴尺度与对象合同</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>九轴尺度画像（scale_profile）</td><td>SP=&lt;A,X,T,O,C,R,I,N,J&gt;；A=聚合层次：关系或事件单元、候选成员总体、边界内外分布及分组规则；X=空间范围：共同场所、组织边界、数字平台与跨域外部环境；T=时间跨度：识别窗口、成员变动周期与边界历史；O=组织层级：角色、团队、组织、制度至治理生态；C=因果层次：原始事件、互动机制、中观关系结构、制度与系统条件；R=观察分辨率：原始互动、事件序列、成员个案、边界分布、指标与摘要，并登记压缩损失；I=影响范围：直接成员、被排除者、间接受影响者、二阶外溢、跨域与代际位置；N=网络拓扑范围：成员关系、边界连接、孤立点与跨域桥接；J=管辖与授权范围：对象命名、边界采用及后续处置分别登记授权；不适用轴须登记not_applicable理由</td></tr><tr><td>有效对象（effective_object）</td><td>由D0声明的候选对象；只有通过预注册G1-instance相对匹配N0的阈值检验后，才在该实例范围登记为有限有效结构域</td></tr><tr><td>跨尺度保持项（scale_invariants）</td><td>1. 对象合同2. 参与与受影响位置</td></tr><tr><td>升格必补项（required_scale_additions）</td><td>1. 单位与总体<br>2. 代表性<br>3. J轴<br>4. 低可见位置</td></tr><tr><td>随尺度改变项（changing_semantics）</td><td>1. 有效成员、关系和同一性可随尺度改变</td></tr><tr><td>不适用对象（non_applicable_objects）</td><td>1. 无意向、制度或责任接口的非人系统</td></tr><tr><td>禁止升格（forbidden_elevation）</td><td>1. 局部群体直接代表全部受影响者</td></tr></tbody></table></div><p>D. 状态、证据与变量流</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>状态集合（state）</td><td>1. 候选2. 可识别3. 边界争议4. 不成立</td></tr><tr><td>可观测项（observables）</td><td>1. 边界内外关系密度与约束差异<br>2. 成员进入、退出与被排除记录<br>3. 共同问题、资源通道或制度规则的重复共现<br>4. 改变分组规则后对象识别是否稳定</td></tr><tr><td>证据要求（evidence）</td><td>1. D0候选对象与同一性记录<br>2. G1-instance预注册表及匹配N0<br>3. 训练与样本外或外推结果<br>4. 候选分组与竞争分组的增益比较</td></tr><tr><td>输入依赖与接口内容（input_dependencies）</td><td>1. D0只提供候选对象字段，不构成结构成立证据<br>2. 预注册G1-instance及匹配N0、阈值、模型类、样本或外推单位<br>3. 观察位置、竞争分组与E1协议</td></tr><tr><td>输出效应与变量流（output_effects）</td><td>1. R0向其余变量提供候选对象引用、边界、时间窗与不确定性；R1另提供G1所支持的有限有效范围<br>2. 对象存在及领域事实的依据与分组增益分别保留</td></tr><tr><td>时间窗与时滞（time_window_and_lag）</td><td>登记识别窗口、边界变动与成员变化时滞</td></tr><tr><td>不确定性（uncertainty）</td><td>记录边界争议、成员缺席和观察覆盖</td></tr><tr><td>局部排除区（local_exclusion_zone）</td><td>无法安全表达或未被采样的位置不得被总体代表</td></tr><tr><td>受影响位置（affected_positions）</td><td>1. 成员2. 被排除者3. 边界外成本承担者</td></tr></tbody></table></div><p>E. 承接、责任、规范、上限与纠错</p><div class="xk-table"><table><thead><tr><th>字段</th><th>登记内容</th></tr></thead><tbody><tr><td>承接载体（carrier）</td><td>1. 关系网络2. 组织边界3. 制度记录</td></tr><tr><td>责任主体（responsible_subject）</td><td>1. 提出结构域判断的分析者<br>2. 使用该判断的决策者</td></tr><tr><td>规范地位（normative_status）</td><td>描述性H-World接口，不产生正当性</td></tr><tr><td>判断上限（judgment_ceiling）</td><td>只有G1-instance通过时，且仅限预注册对象、尺度、窗口、结果与外推单位，才可登记解释级有限有效对象；否则仅为候选对象或材料集合</td></tr><tr><td>行动上限（action_ceiling）</td><td>本变量只生成候选结构域、边界争议与补证需求描述，不授权纳入、排除或处置；任何现实调整须另过C12、运行时显式N前提、J授权与O程序</td></tr><tr><td>反例（counterexamples）</td><td>1. 同一场所中反复共现的人群没有稳定关系或共同约束<br>2. 分析者划定的群组在改变分组规则后立即消失</td></tr><tr><td>申诉（appeal）</td><td>依appeal_and_rollback_rule，成员与受影响位置可经安全可达、反报复通道挑战边界、代表性和同一性判据，并触发与原命名或决策链独立的复核</td></tr><tr><td>回滚（rollback）</td><td>依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内实际撤销结构域登记、移除其对下游对象范围的效力并恢复为材料集合，保留版本与完成验证</td></tr></tbody></table></div></div>',1)),d(e,{section:"A.1"}),t[1]||(t[1]=o("div",{class:"theory-source"},null,-1))])}const T=a(l,[["render",c]]);export{h as __pageData,T as default};
